add_action( 'woocommerce_product_query', 'perfectpixel_last_chance_category' );

function perfectpixel_last_chance_category( $q ) {
	$category = (int) '{{last_chance_category_id}}';
	if ( ! $category || ! is_product_category() || get_queried_object_id() !== $category ) {
		return;
	}
	$ids = wc_get_product_ids_on_sale();
	$q->set( 'product_cat', '' );
	$q->set( 'tax_query', array() );
	$q->set( 'post__in', $ids ? array_values( array_unique( array_map( 'intval', $ids ) ) ) : array( 0 ) );
	$q->set(
		'meta_query',
		array(
			'pp_sale_end' => array(
				'key'     => '_sale_price_dates_to',
				'value'   => time(),
				'compare' => '>',
				'type'    => 'NUMERIC',
			),
		)
	);
	$q->set( 'orderby', array( 'pp_sale_end' => 'ASC' ) );
}
